-- INSERT script for helpdesk_tickets (source: 'Cleaned Data' sheet, 1515 rows)

CREATE TABLE IF NOT EXISTS helpdesk_tickets (
    `Status` VARCHAR(50),
    `Ticket ID` INT NOT NULL PRIMARY KEY,
    `Priority` VARCHAR(30),
    `Source` VARCHAR(50),
    `Topic` VARCHAR(150),
    `Agent Group` VARCHAR(100),
    `Agent Name` VARCHAR(100),
    `Created time` DATETIME,
    `Expected SLA to resolve` DATETIME,
    `Expected SLA to first response` DATETIME,
    `First response time` DATETIME,
    `SLA For first response` VARCHAR(20),
    `Resolution time` DATETIME,
    `SLA For Resolution` VARCHAR(20),
    `Close time` DATETIME,
    `Agent interactions` DECIMAL(10,2),
    `Survey results` VARCHAR(50),
    `Product group` VARCHAR(100),
    `Support Level` VARCHAR(30),
    `Country` VARCHAR(100),
    `Response Duration (min)` DECIMAL(12,4),
    `Resolution Duration (min)` DECIMAL(12,4),
    `Response SLA Difference (min)` DECIMAL(12,4),
    `Resolution SLA Difference (min)` DECIMAL(12,4),
    `Resolution SLA Validation` VARCHAR(50),
    `Response SLA Validation` VARCHAR(50),
    INDEX idx_created_time (`Created time`),
    INDEX idx_priority (`Priority`),
    INDEX idx_status (`Status`),
    INDEX idx_topic (`Topic`),
    INDEX idx_agent_group (`Agent Group`)
);
















